class DcrInitialAccessTokenExpiresAtAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getExpiresAt returns null on a freshly created holder.
     */
    public function testExpiresAtNotAssignedByDefault(): void
    {
        // Arrange
